ALTER POLICY asset_document_storage_read ON storage.objects USING (bucket_id = 'asset-documents' AND EXISTS (SELECT 1 FROM public.assets a WHERE a.organization_id::text = (storage.foldername(storage.objects.name))[1] AND a.id::text = (storage.foldername(storage.objects.name))[2] AND public.is_org_member(a.organization_id)));
ALTER POLICY asset_document_storage_add ON storage.objects WITH CHECK (bucket_id = 'asset-documents' AND EXISTS (SELECT 1 FROM public.assets a WHERE a.organization_id::text = (storage.foldername(storage.objects.name))[1] AND a.id::text = (storage.foldername(storage.objects.name))[2] AND public.is_org_member(a.organization_id)));
ALTER POLICY asset_document_storage_cleanup ON storage.objects USING (bucket_id = 'asset-documents' AND owner_id::text = auth.uid()::text AND NOT EXISTS (SELECT 1 FROM public.asset_attachments d WHERE d.storage_path = storage.objects.name) AND EXISTS (SELECT 1 FROM public.assets a WHERE a.organization_id::text = (storage.foldername(storage.objects.name))[1] AND a.id::text = (storage.foldername(storage.objects.name))[2] AND public.is_org_member(a.organization_id)));